def string_sequence(n: int) -> str:
    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence(0)
    '0'
    >>> string_sequence(5)
    '0 1 2 3 4 5'
    """
    if n < 0:
        return ''
    return ' '.join(str(i) for i in range(n + 1))

import math

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n <= 1:
        raise ValueError("n must be greater than 1 to have a proper divisor smaller than itself")
    # Even numbers: largest proper divisor is n // 2
    if n % 2 == 0:
        return n // 2
    # Search for smallest odd divisor >=3; then largest proper divisor is n // d
    limit = int(math.isqrt(n))
    for i in range(3, limit + 1, 2):
        if n % i == 0:
            return n // i
    # If no divisor found, n is prime; largest proper divisor is 1
    return 1

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result_chars = []
    for c in string:
        if c.islower():
            result_chars.append(c.upper())
        elif c.isupper():
            result_chars.append(c.lower())
        else:
            result_chars.append(c)
    return ''.join(result_chars)

def get_positive(l: list):
    """Return only positive numbers in the list.
    >>> get_positive([-1, 2, -4, 5, 6])
    [2, 5, 6]
    >>> get_positive([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10])
    [5, 3, 2, 3, 9, 123, 1]
    """
    if l is None:
        return []
    result = []
    for x in l:
        try:
            if x > 0:
                result.append(x)
        except TypeError:
            # Skip elements that cannot be compared to 0 (e.g., strings)
            continue
    return result

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    # Try fast path: use a set for deduplication (works for hashable items)
    try:
        dedup = set(l)
    except TypeError:
        # Fallback for unhashable items: preserve first-seen order
        dedup_list = []
        for item in l:
            already_seen = False
            for s in dedup_list:
                if item == s:
                    already_seen = True
                    break
            if not already_seen:
                dedup_list.append(item)
        # Attempt to return sorted if possible, otherwise return as-is
        try:
            return sorted(dedup_list)
        except TypeError:
            return dedup_list

    # dedup is a set of unique items; try to sort and return
    try:
        return sorted(dedup)
    except TypeError:
        # If items are not mutually comparable, return as list (order arbitrary)
        return list(dedup)

def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str) -> str:
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def common(l1: list, l2: list):
    """Return sorted unique common elements for two lists.
    >>> common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121])
    [1, 5, 653]
    >>> common([5, 3, 2, 8], [3, 2])
    [2, 3]
    """
    # Use sets to remove duplicates and compute intersection
    s1 = set(l1)
    s2 = set(l2)
    common_set = s1 & s2

    # Try normal sorting; if elements are not directly comparable, sort by string representation
    try:
        return sorted(common_set)
    except TypeError:
        return sorted(common_set, key=lambda x: str(x))

# Chain-of-Thought / Pseudocode:
# - We need to determine if an integer `a` (< 100) can be written as a product of exactly three primes.
# - Primes here are the standard primes (2, 3, 5, ...). Repetition of primes is allowed (e.g., 8 = 2*2*2).
# - The smallest possible product of three primes is 2*2*2 = 8, so if a < 8 we can return False immediately.
# - Approach:
#   1. Implement an is_prime(n) helper to check primality for small n.
#   2. For each prime p that divides a, compute rem = a // p.
#   3. Check whether rem can be expressed as a product of two primes:
#        - Iterate over primes q (or just integers >=2) and if rem % q == 0 and (rem // q) is prime, then success.
#   4. If any such decomposition exists, return True; otherwise return False.
# - This is efficient given the small bound (a < 100).
#
# Now implement the function.

def is_multiply_prime(a):
    """Return True if `a` equals the product of exactly three prime numbers (primes may repeat), else False.
    Assumes a is an integer (problem states a < 100).
    """
    # Quick checks
    try:
        n = int(a)
    except Exception:
        return False
    if n < 8:
        return False  # smallest product of three primes is 2*2*2 = 8

    # helper: simple primality test for small numbers
    def is_prime(x):
        if x <= 1:
            return False
        if x <= 3:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    # For each prime p dividing n, check if the quotient can be product of two primes
    for p in range(2, n + 1):
        if not is_prime(p):
            continue
        if n % p != 0:
            continue
        rem = n // p
        # Now check if rem is product of two primes (q * r)
        # q should be >=2 and prime, r = rem // q must be prime as well
        for q in range(2, rem + 1):
            if not is_prime(q):
                continue
            if rem % q != 0:
                continue
            r = rem // q
            if is_prime(r):
                return True

    return False

def numerical_letter_grade(grades):
    """Convert a list of numeric GPAs to letter grades using the specified rules.

    Table:
             GPA       |    Letter grade
              4.0                A+
            > 3.7                A 
            > 3.3                A- 
            > 3.0                B+
            > 2.7                B 
            > 2.3                B-
            > 2.0                C+
            > 1.7                C
            > 1.3                C-
            > 1.0                D+ 
            > 0.7                D 
            > 0.0                D-
              0.0                E

    Any non-numeric or out-of-range values (including negative or NaN) are mapped to 'E'.
    """
    result = []
    for g in grades:
        try:
            val = float(g)
        except Exception:
            result.append('E')
            continue

        # Treat values >= 4.0 as A+, and values <= 0.0 as E (covers 0.0 and negatives).
        if val >= 4.0:
            result.append('A+')
        elif val > 3.7:
            result.append('A')
        elif val > 3.3:
            result.append('A-')
        elif val > 3.0:
            result.append('B+')
        elif val > 2.7:
            result.append('B')
        elif val > 2.3:
            result.append('B-')
        elif val > 2.0:
            result.append('C+')
        elif val > 1.7:
            result.append('C')
        elif val > 1.3:
            result.append('C-')
        elif val > 1.0:
            result.append('D+')
