def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated by 4 positions.
    Letters are shifted forward by 4 (wrapping around). Case is preserved;
    non-letter characters are left unchanged.
    """
    shift = 4
    result_chars = []

    for ch in s:
        # lowercase letters
        if 'a' <= ch <= 'z':
            new_ord = (ord(ch) - ord('a') + shift) % 26 + ord('a')
            result_chars.append(chr(new_ord))
        # uppercase letters
        elif 'A' <= ch <= 'Z':
            new_ord = (ord(ch) - ord('A') + shift) % 26 + ord('A')
            result_chars.append(chr(new_ord))
        else:
            # leave other characters unchanged
            result_chars.append(ch)

    return ''.join(result_chars)

def any_int(x, y, z):
    '''
    Create a function that takes 3 numbers.
    Returns true if one of the numbers is equal to the sum of the other two, and all numbers are integers.
    Returns false in any other cases.
    '''
    # Require that all inputs are of exact int type (exclude floats, booleans, etc.)
    for v in (x, y, z):
        if type(v) is not int:
            return False

    a, b, c = x, y, z
    return (a == b + c) or (b == a + c) or (c == a + b)

def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    # helper to shift a single letter by n positions, preserving case
    def shift_letter(ch, n):
        if 'a' <= ch <= 'z':
            return chr((ord(ch) - ord('a') + n) % 26 + ord('a'))
        if 'A' <= ch <= 'Z':
            return chr((ord(ch) - ord('A') + n) % 26 + ord('A'))
        return ch  # non-letter, unchanged

    vowels = set('aeiouAEIOU')
    result = []

    for ch in message:
        swapped = ch.swapcase()
        if swapped in vowels:
            result.append(shift_letter(swapped, 2))
        else:
            result.append(swapped)

    return ''.join(result)

