                count += 1
    return count

def minPath(grid, k):
    """
    Given an N x N grid containing the numbers 1..N*N exactly once,
    return the lexicographically smallest path of length k (list of cell values)
    where you may start at any cell and at each step move to an orthogonally
    adjacent cell. A path of length k visits exactly k cells (cells may repeat).
    """
    if k <= 0:
        return []
    if not grid or not grid[0]:
        return []

    n = len(grid)
    m = len(grid[0])

    # find minimal value for the first element (guaranteed unique set contains 1..N*N, so it's global min)
    min_val = min(min(row) for row in grid)

    # initialize positions that have this minimal starting value
    positions = {(r, c) for r in range(n) for c in range(m) if grid[r][c] == min_val}

    path = [min_val]
    if k == 1:
        return path

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for _ in range(k - 1):
        # collect neighbors reachable in one move from any current position
        neighbors = set()
        for r, c in positions:
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    neighbors.add((nr, nc))
        if not neighbors:
            break
        # find minimal value among these neighbors
        min_next = min(grid[r][c] for r, c in neighbors)
        # restrict positions to those neighbors having the minimal next value
        positions = {(r, c) for (r, c) in neighbors if grid[r][c] == min_next}
        path.append(min_next)

    return path

def sum_squares(lst):
    """
    This function will take a list of integers. For all entries in the list, the function shall square the integer entry if its index is a 
    multiple of 3 and will cube the integer entry if its index is a multiple of 4 and not a multiple of 3. The function will not 
    change the entries in the list whose indexes are not a multiple of 3 or 4. The function shall then return the sum of all entries. 
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val * val
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

def words_in_sentence(sentence):
    """
    You are given a string representing a sentence,
    the sentence contains some words separated by a space,
    and you have to return a string that contains the words from the original sentence,
    whose lengths are prime numbers,
    the order of the words in the new string should be the same as the original one.
    """
    import math

    def is_prime(n):
        if n < 2:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0:
            return False
        limit = int(math.isqrt(n))
        for i in range(3, limit + 1, 2):
            if n % i == 0:
                return False
        return True

    # Split on whitespace to be robust to multiple spaces
    words = sentence.split()
    result = [w for w in words if is_prime(len(w))]
    return " ".join(result)

def get_max_triples(n):
    """
    You are given a positive integer n. You have to create an integer array a of length n.
        For each i (1 ≤ i ≤ n), the value of a[i] = i * i - i + 1.
        Return the number of triples (a[i], a[j], a[k]) of a where i < j < k, 
    and a[i] + a[j] + a[k] is a multiple of 3.
    """
    # count of indices i in 1..n with i % 3 == 2
    if n < 2:
        c0 = 0
    else:
        c0 = (n - 2) // 3 + 1
    c1 = n - c0

    def comb3(x):
        if x < 3:
            return 0
        return (x * (x - 1) * (x - 2)) // 6

    return comb3(c0) + comb3(c1)

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5
    """
    # Accept integral floats like 7.0, reject non-integral inputs as non-prime
    if not isinstance(n, int):
        if isinstance(n, float) and n.is_integer():
            n = int(n)
        else:
            return y

    # Numbers less than 2 are not prime
    if n < 2:
        return y
    # 2 and 3 are prime
    if n == 2 or n == 3:
        return x
    # Multiples of 2 or 3 are not prime
    if n % 2 == 0 or n % 3 == 0:
        return y

    # Check divisors of form 6k ± 1 up to sqrt(n)
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return y
        i += 6

    return x

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    # Work with absolute value to ignore sign
    n = abs(int(num))

    # Special-case zero since str(0) is fine but handle explicitly for clarity
    if n == 0:
        return (1, 0)

    even_count = 0
    odd_count = 0

    for ch in str(n):
        d = ord(ch) - ord('0')  # convert char to int without int()
        if d % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

import math

def right_angle_triangle(a, b, c):
