    for s in sides:
        if not math.isfinite(s) or s <= 0:
            return False

    sides.sort()
    x, y, z = sides  # x <= y <= z

    # Must satisfy strict triangle inequality (degenerate triangles are not valid)
    if x + y <= z:
        return False

    # Check Pythagorean theorem with tolerance for floating point inputs
    return math.isclose(x * x + y * y, z * z, rel_tol=1e-9, abs_tol=1e-12)

def do_algebra(operator, operand):
    """
    Given two lists operator, and operand. The first list has basic algebra operations, and 
    the second list is a list of integers. Use the two given lists to build the algebraic 
    expression and return the evaluation of this expression.

    Supported operators: '+', '-', '*', '//', '**'
    """
    # Define precedence and associativity
    precedence = {
        '**': 4,
        '*': 3,
        '//': 3,
        '+': 2,
        '-': 2
    }
    # True if operator is right-associative
    right_assoc = {
        '**': True,
        '*': False,
        '//': False,
        '+': False,
        '-': False
    }

    # Build token list: operand0, op0, operand1, op1, operand2, ...
    tokens = []
    n_ops = len(operator)
    for i in range(n_ops):
        tokens.append(operand[i])
        tokens.append(operator[i])
    tokens.append(operand[-1])

    # Shunting-yard: convert to RPN
    output_queue = []
    op_stack = []

    for tok in tokens:
        if isinstance(tok, int):
            output_queue.append(tok)
        else:
            # tok is operator string
            o1 = tok
            while op_stack:
                o2 = op_stack[-1]
                if o2 not in precedence:
                    break
                p1 = precedence[o1]
                p2 = precedence[o2]
                if (not right_assoc.get(o1, False) and p1 <= p2) or (right_assoc.get(o1, False) and p1 < p2):
                    output_queue.append(op_stack.pop())
                else:
                    break
            op_stack.append(o1)

    while op_stack:
        output_queue.append(op_stack.pop())

    # Evaluate RPN
    eval_stack = []
    for tok in output_queue:
        if isinstance(tok, int):
            eval_stack.append(tok)
        else:
            # binary operator: pop right then left
            right = eval_stack.pop()
            left = eval_stack.pop()
            if tok == '+':
                res = left + right
            elif tok == '-':
                res = left - right
            elif tok == '*':
                res = left * right
            elif tok == '//':
                # floor division, mimic Python's behavior
                res = left // right
            elif tok == '**':
                res = left ** right
            else:
                raise ValueError(f"Unsupported operator: {tok}")
            eval_stack.append(res)

    return eval_stack[0]

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    # If explicit None provided, return None
    if text is None:
        return None

    # If input is bytes, handle directly
    if isinstance(text, bytes):
        if len(text) == 0:
            return None
        data = text
    else:
        # Ensure we have a string representation
        s = text if isinstance(text, str) else str(text)
        if s == "":
            return None
        data = s.encode('utf-8')

    return hashlib.md5(data).hexdigest()
